"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[164],{7783:(e,t,a)=>{a.d(t,{L2:()=>l,LT:()=>i,NG:()=>o});let s="원문 전사: Perseus Digital Library 고정판, CC BY-SA 4.0. 원문은 발췌하고 공백을 정리함. 한국어는 자체 번역.",l="2026-09-30",o=["전체","직접 인용","동일 사건의 외부 기록","동시대 제도 자료","문화적 평행","문학적 모방설"],i=[{id:"josephus-judas-census",actsReference:"행 5:37",eventIds:["a02-08"],relation:"동일 사건의 외부 기록",title:"호적 조사에 맞선 갈릴리 유다",author:"플라비우스 요세푸스",work:"『유대 고대사』",citation:"18.4, 23",date:"AD 6년의 봉기, 약 AD 93-94 기록",language:"고대 그리스어",lang:"grc",lead:"요세푸스는 유다가 로마의 재산 평가를 예속으로 여기며 반대를 선동했다고 기록한다.",context:"4절은 유다를 가울라니티스의 가말라 출신으로 소개하고, 23절은 ‘갈릴리 유다’라고 부르며 그가 이끈 집단의 자유 이념을 설명한다.",lines:[{locator:"\xa74",original:"Ἰούδας δὲ Γαυλανίτης ἀνὴρ ἐκ πόλεως ὄνομα Γάμαλα Σάδδωκον Φαρισαῖον προσλαβόμενος ἠπείγετο ἐπὶ ἀποστάσει, τήν τε ἀποτίμησιν οὐδὲν ἄλλο ἢ ἄντικρυς δουλείαν ἐπιφέρειν λέγοντες καὶ τῆς ἐλευθερίας ἐπʼ ἀντιλήψει παρακαλοῦντες τὸ ἔθνος\xb7",translation:"가울라니티스의 가말라라는 성읍 출신인 유다는 바리새인 사독을 동료로 삼아 반란을 부추겼다. 이들은 재산 평가가 명백한 예속을 가져올 뿐이라고 말하며 민족에게 자유를 지키라고 촉구했다."},{locator:"\xa723, 앞부분",original:"Τῇ δὲ τετάρτῃ τῶν φιλοσοφιῶν ὁ Γαλιλαῖος Ἰούδας ἡγεμὼν κατέστη, τὰ μὲν λοιπὰ πάντα γνώμῃ τῶν Φαρισαίων ὁμολογούσῃ, δυσνίκητος δὲ τοῦ ἐλευθέρου ἔρως ἐστὶν αὐτοῖς μόνον ἡγεμόνα καὶ δεσπότην τὸν θεὸν ὑπειληφόσιν.",translation:"넷째 사상 집단은 갈릴리 유다가 지도자가 되었다. 다른 견해는 바리새인들과 같았지만, 이들은 하나님만을 지도자와 주인으로 여겨 자유에 대한 열망을 꺾기 어려웠다."}],connection:"사도행전 5장 37절도 갈릴리 유다가 호적 조사 때 사람들을 자기 뒤로 이끌었다고 말한다. 요세푸스는 세금 평가를 예속으로 이해한 정치적 동기와 하나님만을 주인으로 삼는 신념을 덧붙인다. 두 자료를 대조하면 가말리엘이 언급한 운동의 배경이 구체적으로 드러난다.",caution:"요세푸스의 이 두 단락은 세금 반대와 집단의 신념을 설명한다. 사도행전의 가말리엘 연설은 유다가 죽고 따르던 사람들이 흩어진 일을 사도들의 현재 상황과 비교한다. 인물의 활동 배경과 연설에서 그 사례를 사용하는 목적이 각각 다르다.",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 5장 35-39절 주해.",edition:"B. Niese 편, Flavii Iosephi opera, 1-4권, Berlin: Weidmann, 1885-1890. Perseus 고정 전사본.",license:s,sources:[{label:"Perseus 고정판 원문(XML)",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0526/tlg001/tlg0526.tlg001.perseus-grc2.xml"},{label:"고정판 판본 정보",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0526/tlg001/__cts__.xml"},{label:"원문 이용 조건(CC BY-SA 4.0)",url:"https://creativecommons.org/licenses/by-sa/4.0/"}],keywords:["유다","갈릴리","가말리엘","호적","세금","쿠레니오","구레뇨","자유","요세푸스"]},{id:"josephus-helena-famine",actsReference:"행 11:27-30",eventIds:["a04-09"],relation:"문화적 평행",title:"헬레나 여왕의 기근 구호",author:"플라비우스 요세푸스",work:"『유대 고대사』",citation:"20.51-53, 101",date:"1세기 중반의 기근, 약 AD 93-94 기록",language:"고대 그리스어",lang:"grc",lead:"헬레나 여왕은 예루살렘의 기근에 대응해 이집트의 곡물과 구브로의 말린 무화과를 들여와 나누어 준다.",context:"요세푸스는 여왕의 구호 활동과 아들 이자테스가 예루살렘 지도자들에게 보낸 돈을 기록한다. 다른 단락인 101절도 유대의 큰 기근과 헬레나의 곡물 구입을 다시 언급한다.",lines:[{locator:"\xa751",original:"γίνεται δὲ αὐτῆς ἡ ἄφιξις πάνυ συμφέρουσα τοῖς Ἱεροσολυμίταις\xb7 λιμοῦ γὰρ αὐτῶν τὴν πόλιν κατὰ τὸν καιρὸν ἐκεῖνον πιεζοῦντος καὶ πολλῶν ὑπʼ ἐνδείας ἀναλωμάτων φθειρομένων ἡ βασιλὶς Ἑλένη πέμπει τινὰς τῶν ἑαυτῆς, τοὺς μὲν εἰς τὴν Ἀλεξάνδρειαν πολλῶν σῖτον ὠνησομένους χρημάτων, τοὺς δʼ εἰς Κύπρον ἰσχάδων φόρτον οἴσοντας.",translation:"그녀의 도착은 예루살렘 사람들에게 큰 도움이 되었다. 그때 기근이 성읍을 압박하고 생필품이 없어 많은 사람이 죽어 가자, 헬레나 여왕은 자기 사람들을 보냈다. 일부는 큰돈을 들여 곡물을 사도록 알렉산드리아로, 다른 이들은 말린 무화과를 실어 오도록 구브로로 보냈다."},{locator:"\xa752-53",original:"ὡς δʼ ἐπανῆλθον ταχέως κομίζοντες τοῖς ἀπορουμένοις διένειμε τροφὴν καὶ μεγίστην αὐτῆς μνήμην τῆς εὐποιίας ταύτης εἰς τὸ πᾶν ἡμῶν ἔθνος καταλέλοιπε. πυθόμενος δὲ καὶ ὁ παῖς αὐτῆς Ἰζάτης τὰ περὶ τὸν λιμὸν ἔπεμψε πολλὰ χρήματα τοῖς πρώτοις τῶν Ἱεροσολυμιτῶν. ἀλλὰ γὰρ ἃ τοῖς βασιλεῦσιν εἰς τὴν πόλιν ἡμῶν ἀγαθὰ πέπρακται μετὰ ταῦτα δηλώσομεν.",translation:"그들이 물품을 가져와 빨리 돌아오자 여왕은 어려운 사람들에게 식량을 나누어 주었다. 이 선행은 우리 민족 전체에 큰 기억을 남겼다. 그녀의 아들 이자테스도 기근 소식을 듣고 예루살렘의 지도자들에게 많은 돈을 보냈다. 이 왕들이 우리 성읍에 베푼 좋은 일들은 뒤에서 설명하겠다."}],connection:"사도행전 11장 28-30절은 클라우디우스 때의 기근과 안디옥 신자들이 유대에 보낸 구호금을 기록한다. 요세푸스의 헬레나\xb7이자테스 기록은 유대의 기근에 외부에서 식량과 돈을 보내던 다른 구호 사례를 보여 준다. 구호의 발신지와 주체가 다르면서도 예루살렘과 유대로 지원이 모이는 양상이 공통된다.",caution:"사도행전은 아가보의 예언과 안디옥 공동체의 지원을, 요세푸스는 왕실의 식량 구입과 지원을 서술한다. 사도행전의 예언 범위는 οἰκουμένη(로마 세계)이고, 여기 제시한 요세푸스 기록의 구호 대상은 예루살렘과 유대다.",commentary:"Luke Timothy Johnson, The Acts of the Apostles, 206쪽(사도행전 11장 28-30절 주해).",edition:"B. Niese 편, Flavii Iosephi opera, 1-4권, Berlin: Weidmann, 1885-1890. Perseus 고정 전사본.",license:s,sources:[{label:"Perseus 고정판 원문(XML)",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0526/tlg001/tlg0526.tlg001.perseus-grc2.xml"},{label:"고정판 판본 정보",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0526/tlg001/__cts__.xml"},{label:"원문 이용 조건(CC BY-SA 4.0)",url:"https://creativecommons.org/licenses/by-sa/4.0/"}],keywords:["기근","구호","헬레나","이자테스","아가보","안디옥","예루살렘","클라우디우스","글라우디오"]},{id:"josephus-agrippa-death",actsReference:"행 12:20-23",eventIds:["a04-11"],relation:"동일 사건의 외부 기록",title:"신으로 불린 아그립바의 죽음",author:"플라비우스 요세푸스",work:"『유대 고대사』",citation:"19.344-346, 350",date:"약 AD 93-94 기록",language:"고대 그리스어",lang:"grc",lead:"요세푸스도 가이사랴의 축제에서 아그립바가 신으로 불린 뒤 심한 통증을 겪었다고 기록한다.",lines:[{locator:"\xa7344",original:"δευτέρᾳ δὴ τῶν θεωριῶν ἡμέρᾳ στολὴν ἐνδὺς ἐξ ἀργύρου πεποιημένην πᾶσαν, ὡς θαυμάσιον ὑφὴν εἶναι, παρῆλθεν εἰς τὸ θέατρον ἀρχομένης ἡμέρας. ἔνθα ταῖς πρώταις τῶν ἡλιακῶν ἀκτίνων ἐπιβολαῖς ὁ ἄργυρος καταυγασθεὶς θαυμασίως ἀπέστιλβε μαρμαίρων τι φοβερὸν καὶ τοῖς εἰς αὐτὸν ἀτενίζουσι φρικῶδες.",translation:"공연 둘째 날, 그는 온통 은으로 정교하게 짠 옷을 입고 날이 밝기 시작할 때 극장에 들어왔다. 은이 첫 햇살을 받아 눈부시게 빛나자, 그를 바라보는 이들에게 두렵고 오싹한 인상을 주었다."},{locator:"\xa7345",original:"εὐθὺς δὲ οἱ κόλακες τὰς οὐδὲ ἐκείνῳ πρὸς ἀγαθοῦ ἄλλος ἄλλοθεν φωνὰς ἀνεβόων, θεὸν προσαγορεύοντες εὐμενής τε εἴης ἐπιλέγοντες, εἰ καὶ μέχρι νῦν ὡς ἄνθρωπον ἐφοβήθημεν,",translation:"곧 아첨꾼들이 사방에서 그에게 이롭지 않은 말들을 외치며 그를 신이라고 불렀다. 그들은 “우리에게 자비로우소서. 지금까지는 당신을 인간으로 두려워했지만”이라고 말했다."},{locator:"\xa7346",original:"ἀλλὰ τοὐντεῦθεν κρείττονά σε θνητῆς φύσεως ὁμολογοῦμεν. οὐκ ἐπέπληξεν τούτοις ὁ βασιλεὺς οὐδὲ τὴν κολακείαν ἀσεβοῦσαν ἀπετρίψατο. ἀνακύψας δʼ οὖν μετʼ ὀλίγον τὸν βουβῶνα τῆς ἑαυτοῦ κεφαλῆς ὑπερκαθιζόμενον εἶδεν ἐπὶ σχοινίου τινός. ἄγγελον τοῦτον εὐθὺς ἐνόησεν κακῶν εἶναι τὸν καί ποτε τῶν ἀγαθῶν γενόμενον, καὶ διακάρδιον ἔσχεν ὀδύνην, ἄθρουν δʼ αὐτῷ τῆς κοιλίας προσέφυσεν ἄλγημα μετὰ σφοδρότητος ἀρξάμενον.",translation:"“이제부터는 당신이 죽을 인간의 본성보다 뛰어나다고 고백합니다.” 왕은 이들을 꾸짖지도, 불경한 아첨을 물리치지도 않았다. 잠시 뒤 고개를 들어 자기 머리 위 밧줄에 앉은 부엉이를 보았다. 그는 전에 좋은 소식을 전했던 그것이 이제 불행의 사자임을 깨달았다. 가슴을 꿰찌르는 듯한 고통을 느꼈고, 갑자기 배에 격렬한 통증이 일어났다."},{locator:"\xa7350",original:"συνεχεῖς δʼ ἐφʼ ἡμέρας πέντε τῷ τῆς γαστρὸς ἀλγήματι διεργασθεὶς τὸν βίον κατέστρεψεν, ἀπὸ γενέσεως ἄγων πεντηκοστὸν ἔτος καὶ τέταρτον, τῆς βασιλείας δʼ ἕβδομον.",translation:"그는 닷새 동안 계속된 복통에 시달리다가 생을 마쳤다. 나이는 쉰넷이었고, 왕으로 다스린 지 일곱 해째였다."}],connection:"두 기록은 아그립바 1세가 가이사랴에서 신적 환호를 받은 뒤 죽은 일을 전한다. 사도행전 12장 22절의 ‘신의 소리’와 요세푸스의 θεὸν προσαγορεύοντες(신이라고 부름)가 대응한다. 사도행전은 하나님께 영광을 돌리지 않은 왕의 죽음 뒤에 말씀이 성장한다는 서술을 잇는다.",caution:"사도행전은 두로\xb7시돈 사람들과의 갈등, 주의 사자, 벌레에 먹힌 죽음을 전한다. 요세푸스는 황제를 위한 축제, 은빛 의복, 부엉이의 징조, 복통과 닷새 뒤의 죽음을 서술한다. 요세푸스의 ἄγγελος는 이 단락에서 부엉이를 불행의 ‘사자’로 풀이하는 말이다.",edition:"B. Niese 편, Flavii Iosephi opera, 1-4권, Berlin: Weidmann, 1885-1890. Perseus 고정 전사본.",license:s,sources:[{label:"Perseus 그리스어 원문",url:"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0145%3Abook%3D19%3Asection%3D344&lang=original"},{label:"Perseus 영역과 대조",url:"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0146%3Abook%3D19%3Asection%3D343"},{label:"Perseus 고정판 원문(XML)",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0526/tlg001/tlg0526.tlg001.perseus-grc2.xml"},{label:"고정판 판본 정보",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0526/tlg001/__cts__.xml"},{label:"원문 이용 조건(CC BY-SA 4.0)",url:"https://creativecommons.org/licenses/by-sa/4.0/"}],keywords:["헤롯","아그립바","가이사랴","신","죽음","요세푸스"],context:"가이사랴에서 황제를 기리는 축제가 열리는 장면이다. 왕의 의복과 군중의 환호, 몸의 통증을 거쳐 마지막 단락에서 죽음에 이르기까지의 시간이 제시된다.",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 12장 20-23절 주해."},{id:"josephus-sardis-synagogue",actsReference:"행 13:14-16; 17:1-2",eventIds:["a05-04b","a07-05"],relation:"동시대 제도 자료",title:"사데의 유대인 모임 장소와 관습",author:"플라비우스 요세푸스가 수록한 사데의 결의문",work:"『유대 고대사』",citation:"14.259-261",date:"기원전 1세기의 결의문, 약 AD 93-94 수록",language:"고대 그리스어",lang:"grc",lead:"사데의 결의문은 유대인들이 관습에 따라 모이고 기도할 장소를 마련하도록 허용한다.",context:"요세푸스가 유대 공동체의 권리와 도시들의 결정을 열거하며 인용한 문서다. 259절은 사데의 의회와 시민들이 채택한 결의임을 밝히고, 뒤의 두 절은 모임\xb7장소\xb7식품 공급을 다룬다.",lines:[{locator:"\xa7260",original:"ἀποκαθισταμένων αὐτοῖς τῶν νόμων καὶ τῆς ἐλευθερίας ὑπὸ τῆς συγκλήτου καὶ τοῦ δήμου τοῦ Ῥωμαίων ἵνα κατὰ τὰ νομιζόμενα ἔθη συνάγωνται καὶ πολιτεύωνται καὶ διαδικάζωνται πρὸς αὑτούς, δοθῇ τε καὶ τόπος αὐτοῖς, εἰς ὃν συλλεγόμενοι μετὰ γυναικῶν καὶ τέκνων ἐπιτελοῦσιν τὰς πατρίους εὐχὰς καὶ θυσίας τῷ θεῷ\xb7",translation:"로마의 원로원과 시민들이 그들의 법과 자유를 회복시켜 주었으므로, 그들은 관습에 따라 모이고 공동체를 이루며 자신들 사이의 일을 판단할 수 있게 해 달라고 요청했다. 또한 여성들과 아이들과 함께 모여 하나님께 조상들의 기도와 제사를 행할 장소도 주어지기를 요청했다."},{locator:"\xa7261",original:"δεδόχθαι τῇ βουλῇ καὶ τῷ δήμῳ συγκεχωρῆσθαι αὐτοῖς συνερχομένοις ἐν ταῖς ἀποδεδειγμέναις ἡμέραις πράσσειν τὰ κατὰ τοὺς αὐτῶν νόμους, ἀφορισθῆναι δʼ αὐτοῖς καὶ τόπον ὑπὸ τῶν στρατηγῶν εἰς οἰκοδομίαν καὶ οἴκησιν αὐτῶν, ὃν ἂν ὑπολάβωσιν πρὸς τοῦτʼ ἐπιτήδειον εἶναι, ὅπως τε τοῖς τῆς πόλεως ἀγορανόμοις ἐπιμελὲς ᾖ καὶ τὰ ἐκείνοις πρὸς τροφὴν ἐπιτήδεια ποιεῖν εἰσάγεσθαι.",translation:"의회와 시민들은 이들이 정해진 날에 모여 자신들의 법에 따른 일을 하도록 허용하기로 결의했다. 적합하다고 여기는 건축과 거처의 장소를 관리들이 배정하고, 도시의 시장 담당자들은 이들의 식생활에 알맞은 식품이 수입되도록 돌보기로 했다."}],connection:"사도행전은 바울이 피시디아 안디옥과 데살로니가의 회당에 들어가 안식일에 성경을 읽고 설명하는 장면을 전한다. 사데의 결의문은 소아시아의 다른 유대 공동체가 정기 모임, 장소, 관습과 식생활을 도시 행정과 조율하던 사례다.",caution:"이 문서는 사데의 공동체와 도시 결정에 관한 기록이다. 사도행전의 두 회당은 피시디아 안디옥과 데살로니가에 있다. 결의문에는 기도와 θυσίαι(제사\xb7봉헌)가, 사도행전에는 성경 낭독과 해설이 강조된다.",edition:"B. Niese 편, Flavii Iosephi opera, 1-4권, Berlin: Weidmann, 1885-1890. Perseus 고정 전사본.",license:s,sources:[{label:"Perseus 고정판 원문(XML)",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0526/tlg001/tlg0526.tlg001.perseus-grc2.xml"},{label:"고정판 판본 정보",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0526/tlg001/__cts__.xml"},{label:"원문 이용 조건(CC BY-SA 4.0)",url:"https://creativecommons.org/licenses/by-sa/4.0/"}],keywords:["사데","회당","디아스포라","유대인","안식일","기도","도시","식품","관습"]},{id:"ovid-baucis-philemon",actsReference:"행 14:8-18",eventIds:["a05-07"],relation:"문화적 평행",title:"여행자의 모습으로 찾아온 두 신",author:"오비디우스",work:"『변신 이야기』",citation:"8.620-634, 689-697",date:"약 AD 8",language:"라틴어",lang:"la",lead:"브루기아의 늙은 부부가 인간 여행자의 모습으로 찾아온 유피테르와 메르쿠리우스를 맞아들인다. 루스드라의 제우스\xb7헤르메스 인식과 환대를 대조할 수 있는 이야기다.",lines:[{locator:"620-621행",original:"Quoque minus dubites, tiliae contermina quercus collibus est Phrygiis modico circumdata muro.",translation:"네가 더는 의심하지 않도록 말하자면, 브루기아의 언덕에는 피나무 곁의 참나무가 있고 낮은 담으로 둘러싸여 있다."},{locator:"626-629행",original:"Iuppiter huc specie mortali cumque parente venit Atlantiades positis caducifer alis. Mille domos adiere locum requiemque petentes, mille domos clausere serae. Tamen una recepit,",translation:"유피테르는 인간의 모습을 하고 이곳에 왔다. 지팡이를 든 아틀라스의 후손도 날개를 내려놓고 아버지와 함께 왔다. 그들은 쉴 곳을 구하며 천 채의 집을 찾았으나, 천 채의 집마다 빗장이 닫혔다. 다만 한 집이 그들을 맞아들였다."},{locator:"630-634행",original:"parva quidem, stipulis et canna tecta palustri; sed pia Baucis anus parilique aetate Philemon illa sunt annis iuncti iuvenalibus, illa consenuere casa paupertatemque fatendo effecere levem nec iniqua mente ferendo.",translation:"그 집은 작았고 볏짚과 늪의 갈대로 지붕을 이은 곳이었다. 경건한 노인 바우키스와 비슷한 나이의 필레몬은 젊을 때 결혼해 그 오두막에서 함께 늙었다. 두 사람은 가난을 인정하고 불평 없이 견디어 그 짐을 가볍게 만들었다."},{locator:"689-694행",original:"“di” que “sumus, meritasque luet vicinia poenas impia” dixerunt; “vobis inmunibus huius esse mali dabitur. Modo vestra relinquite tecta ac nostros comitate gradus et in ardua montis ite simul.” Parent ambo baculisque levati nituntur longo vestigia ponere clivo.",translation:"신들은 “우리는 신들이다. 불경한 이웃들은 마땅한 벌을 받을 것이다. 그러나 너희는 이 재난에서 벗어나게 될 것이다. 이제 집을 떠나 우리의 발걸음을 따라 산의 높은 곳으로 함께 가자”라고 말했다. 두 사람은 순종하여 지팡이에 의지하며 긴 비탈길에 발걸음을 옮기려 애썼다."},{locator:"695-697행",original:"Tantum aberant summo, quantum semel ire sagitta missa potest: flexere oculos et mersa palude cetera prospiciunt, tantum sua tecta manere.",translation:"정상까지 남은 거리는 쏜 화살 하나가 날아갈 정도였다. 두 사람이 눈을 돌려 보니 주변은 모두 늪에 잠겼고 자기들의 집만 남아 있었다."}],connection:"두 신이 인간의 모습으로 방문한다는 전승은 사도행전 14장 11절의 반응과 비교된다. 루스드라 사람들은 바나바를 제우스, 주로 말하던 바울을 헤르메스로 부르며 제사를 준비한다. Johnson과 Dunn은 이런 환대 전승과 루스드라 장면의 관련성을 제안한다. 사도행전의 바나바와 바울은 자신들도 같은 인간이라고 말하고 군중을 살아 계신 하나님께 돌이키려 한다.",caution:"오비디우스의 배경은 브루기아의 언덕이고, 사도행전의 장소는 루가오니아의 루스드라다. 시의 나그네들은 실제로 신들인 반면, 사도들은 자신들에게 드리는 제사를 막는다. 두 본문은 신의 인간 방문이라는 문화적 상상과 그에 대한 서로 다른 응답을 보여 준다.",edition:"Hugo Magnus 편, Die Metamorphosen des P. Ovidius Naso, Gotha: F. A. Perthes, 1892. Perseus 고정 전사본.",license:s,sources:[{label:"Perseus 라틴어 원문",url:"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.02.0029%3Abook%3D8%3Acard%3D612"},{label:"Perseus 고정판 원문(XML)",url:"https://github.com/PerseusDL/canonical-latinLit/blob/cc843833e101992ba54549005273cfe61a33504b/data/phi0959/phi006/phi0959.phi006.perseus-lat2.xml"},{label:"고정판 판본 정보",url:"https://github.com/PerseusDL/canonical-latinLit/blob/cc843833e101992ba54549005273cfe61a33504b/data/phi0959/phi006/__cts__.xml"},{label:"원문 이용 조건(CC BY-SA 4.0)",url:"https://creativecommons.org/licenses/by-sa/4.0/"}],keywords:["루스드라","제우스","헤르메스","유피테르","메르쿠리우스","환대","오비디우스","바우키스","필레몬","브루기아","심판"],context:"라틴어의 유피테르와 메르쿠리우스는 그리스어 이름으로 제우스와 헤르메스에 대응한다. 627행의 Atlantiades(아틀라스의 후손)도 메르쿠리우스를 가리킨다. 이야기의 핵심은 가난한 부부의 환대와 이들을 구해 주는 신들의 응답이다.",commentary:"Luke Timothy Johnson, The Acts of the Apostles, 248쪽(사도행전 14장 11-12절 주해); James D. G. Dunn, The Acts of the Apostles, 사도행전 14장 11-13절 주해."},{id:"cicero-roman-citizen",actsReference:"행 16:37-39; 22:25-29",eventIds:["a07-04","a09-05"],relation:"문화적 평행",title:"로마 시민을 묶고 매질하는 행위",author:"마르쿠스 툴리우스 키케로",work:"『베레스 반박』",citation:"2.5.170",date:"기원전 70년의 고발 연설문",language:"라틴어",lang:"la",lead:"키케로는 로마 시민을 결박하고 매질하고 죽이는 행위를 강한 법적\xb7도덕적 언어로 고발한다.",context:"시칠리아 총독 베레스의 행위를 고발하는 연설문으로, 가비우스라는 로마 시민의 처형을 다룬다. 시민권의 보호를 침해한 일을 법정 청중에게 호소하는 문장이다.",lines:[{locator:"2.5.170, 발췌",original:"facinus est vincire civem Romanum, scelus verberare, prope parricidium necare: quid dicam in crucem tollere? verbo satis digno tam nefaria res appellari nullo modo potest.",translation:"로마 시민을 결박하는 것은 범죄이고, 매질하는 것은 사악한 짓이며, 죽이는 것은 거의 친족 살해와 같다. 십자가에 달아 올리는 일은 무엇이라 말해야 하는가? 이처럼 극악한 일을 충분히 표현할 말은 도무지 없다."}],connection:"사도행전 16장 37절에서 바울은 재판도 받지 않은 로마 시민인 자신과 실라를 공개적으로 매질했다고 항의한다. 22장 25절에서는 판결받지 않은 로마 시민에게 채찍질하는 것이 합법인지 묻는다. 키케로의 표현은 이 항의가 전제하는 시민권 보호 규범의 배경을 보여 준다.",caution:"키케로는 기원전 70년 시칠리아에서의 구금\xb7매질\xb7십자가 처형을 고발한다. 사도행전은 1세기의 빌립보에서 이미 받은 매질과 예루살렘에서 예정된 심문용 채찍질을 전한다. 연설의 강한 비난과 각 사건의 법적 절차를 함께 대조할 수 있다.",commentary:"Luke Timothy Johnson, The Acts of the Apostles, 302쪽(사도행전 16장 37-39절 주해).",edition:"William Peterson 편, M. Tulli Ciceronis Orationes, 3권, Oxford: Clarendon Press, 1917. Perseus 고정 전사본.",license:s,sources:[{label:"Perseus 고정판 원문(XML)",url:"https://github.com/PerseusDL/canonical-latinLit/blob/cc843833e101992ba54549005273cfe61a33504b/data/phi0474/phi005/phi0474.phi005.perseus-lat2.xml"},{label:"고정판 판본 정보",url:"https://github.com/PerseusDL/canonical-latinLit/blob/cc843833e101992ba54549005273cfe61a33504b/data/phi0474/phi005/__cts__.xml"},{label:"원문 이용 조건(CC BY-SA 4.0)",url:"https://creativecommons.org/licenses/by-sa/4.0/"}],keywords:["로마","시민권","매질","채찍","결박","키케로","빌립보","백부장","천부장"]},{id:"aratus-offspring",actsReference:"행 17:22-31",eventIds:["a07-07"],relation:"직접 인용",title:"우리 또한 그의 자손이다",author:"아라투스",work:"『파이노메나』",citation:"1-5행",date:"기원전 3세기 전반",language:"고대 그리스어",lang:"grc",lead:"아레오바고 연설의 ‘우리도 그의 소생이라’는 말은 아라투스 5행과 직접 겹친다.",lines:[{locator:"1-4행",original:"ἐκ Διὸς ἀρχώμεσθα, τὸν οὐδέποτʼ ἄνδρες ἐῶμεν ἄρρητον\xb7 μεσταὶ δὲ Διὸς πᾶσαι μὲν ἀγυιαί, πᾶσαι δʼ ἀνθρώπων ἀγοραί, μεστὴ δὲ θάλασσα καὶ λιμένες\xb7 πάντη δὲ Διὸς κεχρήμεθα πάντες.",translation:"제우스에게서 시작하자. 사람들은 결코 그를 말하지 않은 채 두지 않는다. 모든 거리와 인간의 모든 시장이 제우스로 가득하고, 바다와 항구도 가득하다. 어디서나 우리 모두는 제우스를 필요로 한다."},{locator:"5행, 앞부분",original:"τοῦ γὰρ καὶ γένος εἰμέν\xb7",translation:"우리 또한 그의 자손이기 때문이다."}],connection:"사도행전 17장 28절 후반은 Τοῦ γὰρ καὶ γένος ἐσμέν이라고 인용한다. 아라투스의 시적 동사형 εἰμέν은 사도행전에서 ἐσμέν으로 나타난다. 아라투스의 ‘그’는 제우스지만, 바울의 연설은 사람을 하늘과 땅을 지으신 하나님께 속한 존재로 설명하고, 29절에서 금\xb7은\xb7돌로 만든 신상을 비판한다.",caution:"아라투스의 서두에는 제우스가 세상을 채운다는 시적 신관이 있다. 바울의 연설은 창조주, 회개, 심판과 예수님의 부활로 이어진다. 28절 앞부분의 ‘그 안에서 살고 움직이고 존재한다’는 문구는 여기 인용한 아라투스 1-5행에 들어 있지 않다.",edition:"G. R. Mair 편, Callimachus and Lycophron; Aratus, London: William Heinemann; New York: G. P. Putnam’s Sons, 1921. Perseus 고정 전사본.",license:s,sources:[{label:"Perseus 그리스어 원문",url:"https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:2008.01.0483"},{label:"Perseus 판본 정보",url:"https://catalog.perseus.org/catalog/urn:cts:greekLit:tlg0653.tlg001"},{label:"Perseus 고정판 원문(XML)",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0653/tlg001/tlg0653.tlg001.perseus-grc2.xml"},{label:"고정판 판본 정보",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0653/tlg001/__cts__.xml"},{label:"원문 이용 조건(CC BY-SA 4.0)",url:"https://creativecommons.org/licenses/by-sa/4.0/"}],keywords:["아레오바고","아라투스","시인","인용","소생","자손","제우스"],context:"『파이노메나』는 천문 현상을 다루는 교훈시다. 서두는 제우스가 거리\xb7시장\xb7바다\xb7항구를 채우며 사람들이 그에게 의존한다고 노래한다.",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 17장 27-29절 주해."},{id:"pausanias-unknown-gods",actsReference:"행 17:22-23",eventIds:["a07-07"],relation:"문화적 평행",title:"알려지지 않은 신들에게 바친 제단들",author:"파우사니아스",work:"『그리스 여행기』",citation:"1.1.4",date:"기원후 2세기의 기록",language:"고대 그리스어",lang:"grc",lead:"파우사니아스는 아테네 외항 팔레론에서 ‘알려지지 않은 신들’의 제단들을 기록한다.",context:"아테네의 항구와 신전들을 소개하는 여행기 대목이다. 팔레론의 여러 신전과 제단을 열거하며, 알려지지 않은 신들뿐 아니라 영웅들과 테세우스의 아들들, 팔레로스의 제단도 말한다.",lines:[{locator:"1.1.4, 발췌",original:"βωμοὶ δὲ θεῶν τε ὀνομαζομένων Ἀγνώστων καὶ ἡρώων καὶ παίδων τῶν Θησέως καὶ Φαληροῦ\xb7",translation:"또 알려지지 않은 신들이라고 불리는 신들과 영웅들, 테세우스의 아들들, 팔레로스의 제단들이 있다."}],connection:"사도행전 17장 23절에서 바울은 아테네를 돌아보며 ‘알지 못하는 신에게’라고 새긴 제단을 발견했다고 말한다. 파우사니아스의 기록은 신의 이름이나 정체를 특정하지 않는 제단이 그리스 종교 안에 있었다는 비교 자료다. 바울은 이 제단의 명칭을 청중에게 하나님을 설명하는 출발점으로 사용한다.",caution:"파우사니아스의 기록은 2세기 팔레론의 복수 제단과 ‘알려지지 않은 신들’이다. 사도행전은 1세기 아테네의 제단 하나와 단수 Ἀγνώστῳ θεῷ(알지 못하는 신에게)를 말한다. 장소\xb7시기\xb7표현의 수가 서로 다르다.",commentary:"Luke Timothy Johnson, The Acts of the Apostles, 315쪽(사도행전 17장 23절 주해).",edition:"Friedrich Spiro 편, Pausaniae Graeciae Descriptio, Leipzig: Teubner, 1903. Perseus 고정 전사본.",license:s,sources:[{label:"Perseus 고정판 원문(XML)",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0525/tlg001/tlg0525.tlg001.perseus-grc2.xml"},{label:"고정판 판본 정보",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0525/tlg001/__cts__.xml"},{label:"원문 이용 조건(CC BY-SA 4.0)",url:"https://creativecommons.org/licenses/by-sa/4.0/"}],keywords:["아테네","아덴","아레오바고","제단","알지 못하는 신","팔레론","파우사니아스"]},{id:"suetonius-claudius-jews",actsReference:"행 18:1-3",eventIds:["a07-08b"],relation:"동일 사건의 외부 기록",title:"클라우디우스의 로마 유대인 추방",author:"수에토니우스",work:"『황제전』, 클라우디우스",citation:"25.4",date:"약 AD 120 기록, 클라우디우스 재위 AD 41-54",language:"라틴어",lang:"la",lead:"수에토니우스는 클라우디우스가 로마의 유대인들을 추방한 일을 짧게 기록한다.",context:"황제 전기가 로마의 집단과 도시 질서에 관한 정책들을 열거하는 대목이다. Chrestus라는 이름을 붙여 지속적인 소란과 추방을 한 문장으로 설명한다.",lines:[{locator:"25.4, 첫 문장",original:"Iudaeos impulsore Chresto assidue tumultuantis Roma expulit.",translation:"그는 크레스투스의 선동으로 끊임없이 소란을 일으키던 유대인들을 로마에서 추방했다."}],connection:"사도행전 18장 2절은 클라우디우스가 모든 유대인에게 로마를 떠나라고 명령했기 때문에 아굴라와 브리스길라가 고린도로 왔다고 설명한다. 수에토니우스의 문장도 황제와 유대인 추방을 함께 언급하여 그 이동의 역사적 배경을 비교하게 한다.",caution:"수에토니우스는 지속적인 소란과 Chrestus를, 누가는 추방 명령과 아굴라 부부의 이동을 기록한다. Johnson은 Chrestus라는 표현이 로마의 초기 그리스도 관련 논쟁을 반영했을 가능성을 제시한다. 그 해석과 라틴어 본문에 실제로 적힌 이름을 구분해 읽을 수 있다.",commentary:"Luke Timothy Johnson, The Acts of the Apostles, 325쪽(사도행전 18장 1-3절 해설).",edition:"Maximilian Ihm 편, De Vita Caesarum Libri VIII, Leipzig: Teubner, 1908. Perseus 고정 전사본.",license:s,sources:[{label:"Perseus 고정판 원문(XML)",url:"https://github.com/PerseusDL/canonical-latinLit/blob/cc843833e101992ba54549005273cfe61a33504b/data/phi1348/abo015/phi1348.abo015.perseus-lat2.xml"},{label:"고정판 판본 정보",url:"https://github.com/PerseusDL/canonical-latinLit/blob/cc843833e101992ba54549005273cfe61a33504b/data/phi1348/abo015/__cts__.xml"},{label:"원문 이용 조건(CC BY-SA 4.0)",url:"https://creativecommons.org/licenses/by-sa/4.0/"}],keywords:["클라우디우스","글라우디오","로마","유대인","추방","아굴라","브리스길라","Chrestus","크레스투스"]},{id:"gallio-delphi-inscription",actsReference:"행 18:12-17",eventIds:["a07-08b"],relation:"동시대 제도 자료",title:"아가야 총독 갈리오",author:"클라우디우스 황제의 델포이 칙서",work:"갈리오 비문",citation:"SIG\xb3 801D, 5-6행",date:"약 AD 52",language:"고대 그리스어",lang:"grc",lead:"델포이에서 발견된 비문은 갈리오를 아가야의 총독으로 부르며 사도행전의 행정 명칭과 일치한다.",lines:[{locator:"5-6행, 복원 포함",original:"[ΚΑΘΩΣ ΛΟΥΚΙΟΣ ΙΟΥ]ΝΙΟΣ ΓΑΛΛΙΩΝ Ο Φ[ΙΛΟΣ] ΜΟΥ ΚΑ[Ι ΑΝΘΥ]ΠΑΤΟΣ [ΤΗΣ ΑΧΑΙΑΣ ΕΓΡΑΨΕΝ]",translation:"나의 벗이며 아가야의 총독인 루키우스 유니우스 갈리오가 보고한 바에 따르면"}],connection:"사도행전 18장 12절과 비문은 갈리오의 직함을 ἀνθύπατος(총독)로 표시한다. 비문의 황제 칭호와 갈리오의 직위는 바울의 고린도 체류 연대를 정하는 기준이 된다. 이 문서 자체의 주제는 델포이의 도시 문제다.",caution:"비문은 아홉 파편으로 남아 있어 복원된 글자가 섞여 있다. 여기 인용한 문구는 5행 끝과 6행에 걸친다. 바울이나 고린도의 재판은 비문에 나오지 않으며, 갈리오의 이름과 직위를 사도행전의 재판 장면과 대조하는 자료다.",edition:"갈리오 비문(SIG\xb3 801D). K. C. Hanson의 Deissmann\xb7Conzelmann에 근거한 복원 전사와 Plassart의 연구.",license:"고대 비문 원문을 통상적인 복원문으로 제시하고 한국어는 이 사이트에서 번역함.",sources:[{label:"K. C. Hanson 전사와 비문 사진",url:"https://kchanson.com/ANCDOCS/greek/gallio.html"},{label:"A. Plassart의 비문 연구",url:"https://doi.org/10.3406/reg.1967.3963"},{label:"Plassart 논문과 서지",url:"https://www.persee.fr/doc/reg_0035-2039_1967_num_80_379_3963"}],keywords:["갈리오","고린도","아가야","총독","비문","델포이","연대"],context:"황제가 델포이의 인구 감소와 도시 지위 문제에 관해 보낸 문서의 일부다. 갈리오의 이름은 이 사안을 보고한 총독으로 등장한다. 아래 대괄호는 Hanson의 전사에서 복원된 글자에 대응한다.",commentary:"Luke Timothy Johnson, The Acts of the Apostles, 사도행전 18장 12절 주해; Andr\xe9 Plassart, “L’inscription de Delphes mentionnant le proconsul Gallion,” Revue des \xc9tudes Grecques 80, 379-383(1967), 372-378쪽."},{id:"strabo-artemis-temple",actsReference:"행 19:23-35",eventIds:["a08-04"],relation:"동시대 제도 자료",title:"에베소 아데미 신전의 재건과 성역",author:"스트라본",work:"『지리학』",citation:"14.1.22-23",date:"기원전 1세기 말-기원후 1세기 초의 기록",language:"고대 그리스어",lang:"grc",lead:"스트라본은 에베소 주민들의 재산과 봉헌물로 아르테미스 신전을 다시 세운 일과 그 성역을 설명한다.",context:"에베소의 역사와 주요 건축물을 소개하는 지리서 대목이다. 신전 재건 비용, 예술 작품, 사제와 성역의 보호 범위를 함께 다룬다.",lines:[{locator:"14.1.22, 발췌",original:"τὸν δὲ νεὼν τῆς Ἀρτέμιδος πρῶτος μὲν Χερσίφρων ἠρχιτεκτόνησεν, εἶτʼ ἄλλος ἐποίησε μείζω\xb7 ὡς δὲ τοῦτον Ἡρόστρατός τις ἐνέπρησεν, ἄλλον ἀμείνω κατεσκεύασαν συνενέγκαντες τὸν τῶν γυναικῶν κόσμον καὶ τὰς ἰδίας οὐσίας, διαθέμενοι δὲ καὶ τοὺς προτέρους κίονας\xb7",translation:"아르테미스 신전은 처음에 케르시프론이 설계했고, 뒤에 다른 사람이 더 크게 지었다. 헤로스트라토스라는 자가 이를 불태우자, 사람들은 여성들의 장신구와 개인 재산을 모으고 옛 기둥들도 처분하여 더 훌륭한 신전을 세웠다."},{locator:"14.1.23, 발췌",original:"ἄσυλον δὲ μένει τὸ ἱερὸν καὶ νῦν καὶ πρότερον\xb7 τῆς δʼ ἀσυλίας τοὺς ὅρους ἀλλαγῆναι συνέβη πολλάκις,",translation:"이 성소는 지금도 이전처럼 피신처로 남아 있다. 그 보호 구역의 경계는 여러 차례 바뀌었다."}],connection:"사도행전 19장 27절에서 데메드리오는 아데미의 신전과 명성이 위험해진다고 말하고, 35절에서 서기장은 에베소가 여신의 신전을 맡아 돌보는 도시임을 강조한다. 스트라본의 재건과 봉헌 기록은 신전이 공동체의 재산\xb7명예와 결부된 중요한 시설이었음을 보여 준다.",caution:"스트라본의 대목은 큰 신전의 건축\xb7봉헌\xb7성역에 관한 기록이다. 사도행전의 소요는 은으로 아데미 신전 모형을 만드는 장인들의 수입과 도시의 명예가 위협받는다는 주장으로 시작한다. 신전의 지위와 장인들의 주장을 각각 대조하는 자료다.",commentary:"Luke Timothy Johnson, The Acts of the Apostles, 347쪽(사도행전 19장 24절 주해).",edition:"August Meinecke 편, Strabonis Geographica, Leipzig: Teubner, 1877. Perseus 고정 전사본.",license:s,sources:[{label:"Perseus 고정판 원문(XML)",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0099/tlg001/tlg0099.tlg001.perseus-grc2.xml"},{label:"고정판 판본 정보",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0099/tlg001/__cts__.xml"},{label:"원문 이용 조건(CC BY-SA 4.0)",url:"https://creativecommons.org/licenses/by-sa/4.0/"}],keywords:["에베소","아데미","아르테미스","신전","성역","데메드리오","봉헌","재건","스트라본"]},{id:"homer-elpenor-eutychus",actsReference:"행 20:7-12",eventIds:["a08-06"],relation:"문학적 모방설",title:"지붕에서 떨어진 엘페노르",author:"호메로스",work:"『오디세이』",citation:"10.552-560; 12.11-15",date:"전승상 기원전 8-7세기",language:"고대 그리스어",lang:"grc",lead:"엘페노르와 유두고는 모두 높은 곳에서 잠들었다가 떨어진 젊은이지만, 두 이야기의 결말은 정반대다.",lines:[{locator:"10.552-555",original:"Ἐλπήνωρ δέ τις ἔσκε νεώτατος, οὔτε τι λίην ἄλκιμος ἐν πολέμῳ οὔτε φρεσὶν ᾗσιν ἀρηρώς\xb7 ὅς μοι ἄνευθʼ ἑτάρων ἱεροῖς ἐν δώμασι Κίρκης, ψύχεος ἱμείρων, κατελέξατο οἰνοβαρείων.",translation:"엘페노르라는 이가 있었는데 가장 젊었다. 그는 전투에서 그다지 강하지 않았고 판단도 그리 온전하지 않았다. 동료들과 떨어져 키르케의 신성한 집에서 시원한 기운을 찾다가 술에 짓눌린 채 누웠다."},{locator:"10.556-560",original:"κινυμένων δʼ ἑτάρων ὅμαδον καὶ δοῦπον ἀκούσας ἐξαπίνης ἀνόρουσε καὶ ἐκλάθετο φρεσὶν ᾗσιν ἄψορρον καταβῆναι ἰὼν ἐς κλίμακα μακρήν, ἀλλὰ καταντικρὺ τέγεος πέσεν\xb7 ἐκ δέ οἱ αὐχὴν ἀστραγάλων ἐάγη, ψυχὴ δʼ Ἄϊδόσδε κατῆλθεν.",translation:"동료들이 움직이는 소리와 발소리를 듣자 그는 갑자기 일어났다. 긴 사다리로 되돌아가 내려가야 한다는 것을 잊고 지붕에서 곧장 떨어졌다. 목뼈가 부러졌고 그의 혼은 하데스로 내려갔다."},{locator:"12.11-15",original:"φιτροὺς δʼ αἶψα ταμόντες, ὅθʼ ἀκροτάτη πρόεχʼ ἀκτή, θάπτομεν ἀχνύμενοι θαλερὸν κατὰ δάκρυ χέοντες. αὐτὰρ ἐπεὶ νεκρός τʼ ἐκάη καὶ τεύχεα νεκροῦ, τύμβον χεύαντες καὶ ἐπὶ στήλην ἐρύσαντες πήξαμεν ἀκροτάτῳ τύμβῳ ἐυῆρες ἐρετμόν.",translation:"우리는 곧 나무를 베고, 곶이 가장 높이 솟은 곳에서 슬퍼하며 많은 눈물을 흘려 그를 장사지냈다. 시신과 죽은 이의 무구가 다 타자 무덤을 쌓고 비석을 세운 뒤, 무덤 꼭대기에 잘 다듬은 노를 꽂았다."}],connection:"MacDonald는 유두고와 엘페노르 이야기를 문학적 모방 관계로 논의한다. 두 이야기에는 젊은 인물, 높은 곳, 잠과 추락이라는 요소가 겹친다. 사도행전에서는 바울이 유두고를 끌어안고 생명이 그 안에 있다고 말하며, 사람들이 살아 있는 그를 데려와 위로를 받는다.",caution:"엘페노르는 술에 취해 누웠다가 동료들의 소리에 일어나 떨어지고, 유두고는 바울의 긴 강론 중 깊이 잠들어 떨어진다. 호메로스는 장례로 이야기를 잇고 사도행전은 생명 회복으로 마친다. Dunn은 바울의 행동을 열왕기상 17장 21절과 열왕기하 4장 34-35절의 소생 장면과도 연결한다.",edition:"A. T. Murray 판, The Odyssey, London: William Heinemann; New York: G. P. Putnam’s Sons, 1919. Perseus 고정 전사본.",license:s,sources:[{label:"Perseus 그리스어 원문",url:"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0135%3Abook%3D10%3Acard%3D552&lang=original"},{label:"MacDonald의 연구 목록(논문 서문)",url:"https://brill.com/previewpdf/book/edcoll/9789004236219/B9789004236219-s018.xml"},{label:"Sean A. Adams의 사도행전 장르 연구",url:"https://era.ed.ac.uk/items/2a1056b6-7e91-400e-bb82-28bcca9f41a6"},{label:"JHC의 MacDonald 논문 서지 인용",url:"https://depts.drew.edu/jhc/PaulInCorinth.pdf"},{label:"Perseus 고정판 원문(XML)",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0012/tlg002/tlg0012.tlg002.perseus-grc2.xml"},{label:"고정판 판본 정보",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0012/tlg002/__cts__.xml"},{label:"원문 이용 조건(CC BY-SA 4.0)",url:"https://creativecommons.org/licenses/by-sa/4.0/"}],keywords:["유두고","드로아","엘페노르","호메로스","추락","죽음","소생","모방"],context:"오디세우스 일행이 키르케의 섬을 떠날 때, 가장 젊은 동료 엘페노르가 지붕에서 떨어져 죽는다. 12권은 그를 장사지내는 장면을 전한다.",commentary:"Dennis R. MacDonald, “Luke’s Eutychus and Homer’s Elpenor: Acts 20:7-12 and Odyssey 10-12,” Journal of Higher Criticism 1(1994), 5-24쪽; James D. G. Dunn, The Acts of the Apostles, 사도행전 20장 7-10절 주해."},{id:"josephus-egyptian-prophet",actsReference:"행 21:37-39",eventIds:["a09-04"],relation:"동일 사건의 외부 기록",title:"감람산으로 무리를 이끈 이집트인 예언자",author:"플라비우스 요세푸스",work:"『유대 전쟁사』\xb7『유대 고대사』",citation:"전쟁사 2.261-263; 고대사 20.169-171",date:"전쟁사 약 AD 75-79, 고대사 약 AD 93-94 기록",language:"고대 그리스어",lang:"grc",lead:"천부장은 바울을 이집트인 반란 지도자로 오인한다. 요세푸스는 이 인물을 벨릭스 시대의 거짓 예언자로 기록한다.",lines:[{locator:"전쟁사 2.261",original:"Μείζονι δὲ τούτου πληγῇ Ἰουδαίους ἐκάκωσεν ὁ Αἰγύπτιος ψευδοπροφήτης\xb7 παραγενόμενος γὰρ εἰς τὴν χώραν ἄνθρωπος γόης καὶ προφήτου πίστιν ἐπιθεὶς ἑαυτῷ περὶ τρισμυρίους μὲν ἀθροίζει τῶν ἠπατημένων,",translation:"이보다 더 큰 타격으로 유대인들을 해친 자는 이집트인 거짓 예언자였다. 그는 그 땅에 들어온 협잡꾼으로, 자신이 예언자라는 신뢰를 얻어 속은 사람 약 삼만 명을 모았다."},{locator:"전쟁사 2.262",original:"περιαγαγὼν δὲ αὐτοὺς ἐκ τῆς ἐρημίας εἰς τὸ ἐλαιῶν καλούμενον ὄρος ἐκεῖθεν οἷός τε ἦν εἰς Ἱεροσόλυμα παρελθεῖν βιάζεσθαι καὶ κρατήσας τῆς τε Ῥωμαϊκῆς φρουρᾶς καὶ τοῦ δήμου τυραννεῖν χρώμενος τοῖς συνεισπεσοῦσιν δορυφόροις.",translation:"그는 이들을 광야에서 이끌어 감람산이라 불리는 산으로 데려갔다. 거기서 예루살렘에 강제로 들어가 로마 수비대와 민중을 장악하고, 함께 돌입한 무장 호위대를 이용해 지배하려 했다."},{locator:"전쟁사 2.263",original:"φθάνει δʼ αὐτοῦ τὴν ὁρμὴν Φῆλιξ ὑπαντήσας μετὰ τῶν Ῥωμαϊκῶν ὁπλιτῶν, καὶ πᾶς ὁ δῆμος συνεφήψατο τῆς ἀμύνης, ὥστε συμβολῆς γενομένης τὸν μὲν Αἰγύπτιον φυγεῖν μετʼ ὀλίγων, διαφθαρῆναι δὲ καὶ ζωγρηθῆναι πλείστους τῶν σὺν αὐτῷ, τὸ δὲ λοιπὸν πλῆθος σκεδασθὲν ἐπὶ τὴν ἑαυτῶν ἕκαστον διαλαθεῖν.",translation:"벨릭스가 로마 중무장 병사들과 맞서 그의 시도를 먼저 막았고, 온 민중도 방어에 가담했다. 충돌이 일어나자 이집트인은 몇 사람과 함께 달아났다. 그와 함께한 이들 가운데 많은 사람이 죽거나 붙잡혔고, 나머지는 흩어져 각자 숨어들었다."},{locator:"고대사 20.169-170",original:"ἀφικνεῖται δέ τις ἐξ Αἰγύπτου κατὰ τοῦτον τὸν καιρὸν εἰς Ἱεροσόλυμα προφήτης εἶναι λέγων καὶ συμβουλεύων τῷ δημοτικῷ πλήθει σὺν αὐτῷ πρὸς ὄρος τὸ προσαγορευόμενον ἐλαιῶν, ὃ τῆς πόλεως ἄντικρυς κείμενον ἀπέχει στάδια πέντε\xb7 θέλειν γὰρ ἔφασκεν αὐτοῖς ἐκεῖθεν ἐπιδεῖξαι, ὡς κελεύσαντος αὐτοῦ πίπτοι τὰ τῶν Ἱεροσολυμιτῶν τείχη, διʼ ὧν καὶ τὴν εἴσοδον αὐτοῖς παρέξειν ἐπηγγέλλετο.",translation:"그때 이집트에서 어떤 사람이 예루살렘에 와서 자신이 예언자라고 말하며, 대중에게 자기와 함께 감람산이라 불리는 산으로 가라고 권했다. 그 산은 성 맞은편에 있으며 오 스타디온 떨어져 있었다. 그는 그곳에서 자기가 명령하면 예루살렘의 성벽이 무너지는 것을 보여 주고, 그 틈으로 사람들이 들어가게 해 주겠다고 약속했다."}],connection:"사도행전 21장 38절에서 천부장은 바울에게, 광야로 사람들을 이끈 이집트인이 아니냐고 묻는다. 요세푸스의 두 기록은 이런 인물과 군사적 진압이 있었음을 전하며, 감람산과 예루살렘 성벽에 대한 약속을 덧붙인다. 이 배경에서 천부장의 질문은 종교적 예언 활동과 치안 위협을 함께 염두에 둔 오인으로 읽힌다.",caution:"사도행전의 질문은 자객 사천 명을, 『유대 전쟁사』는 속은 사람 약 삼만 명을 말한다. 『유대 고대사』 20.171의 사백 명 사망\xb7이백 명 생포는 진압 결과의 수치다. 각 수치가 가리키는 집단과 서술 단계가 다르다.",edition:"B. Niese 편, Flavii Iosephi opera, 제6권(전쟁사, 1895), 제1-4권(고대사, 1885-1890). Perseus 고정 전사본.",license:s,sources:[{label:"Perseus 그리스어 원문",url:"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0147%3Abook%3D2%3Asection%3D261&lang=original"},{label:"『유대 고대사』의 병행 기록",url:"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0145%3Abook%3D20%3Asection%3D169&lang=original"},{label:"Perseus 고정판 원문(XML)",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0526/tlg004/tlg0526.tlg004.perseus-grc2.xml"},{label:"고정판 판본 정보",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0526/tlg004/__cts__.xml"},{label:"원문 이용 조건(CC BY-SA 4.0)",url:"https://creativecommons.org/licenses/by-sa/4.0/"},{label:"Perseus 고정판 원문(XML)",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0526/tlg001/tlg0526.tlg001.perseus-grc2.xml"},{label:"고정판 판본 정보",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0526/tlg001/__cts__.xml"}],keywords:["이집트인","애굽인","감람산","벨릭스","반란","요세푸스"],context:"로마 총독 벨릭스가 다스리던 시기의 이집트인 지도자에 관한 기록이다. 『유대 전쟁사』는 집단의 규모와 진압을, 『유대 고대사』는 그가 약속한 예언적 징표를 더 자세히 서술한다.",commentary:"Luke Timothy Johnson, The Acts of the Apostles, 사도행전 21장 38절 주해."},{id:"euripides-kicking-goads",actsReference:"행 26:14",eventIds:["a10-05"],relation:"문화적 평행",title:"가시채를 향해 발길질한다는 속담",author:"에우리피데스",work:"『바카이』",citation:"794-795행",date:"기원전 405년경 공연",language:"고대 그리스어",lang:"grc",lead:"『바카이』는 신에게 대항하는 인간을 ‘가시채를 향해 발길질하는’ 모습으로 표현한다.",context:"디오니소스가 펜테우스에게 신을 향해 싸움을 벌이지 말라고 경고하는 대목이다. 가시채는 가축을 몰 때 쓰는 끝이 뾰족한 도구로, 그것을 걷어차면 가축 자신이 다친다는 이미지다.",lines:[{locator:"794-795행",original:"θύοιμʼ ἂν αὐτῷ μᾶλλον ἢ θυμούμενος πρὸς κέντρα λακτίζοιμι θνητὸς ὢν θεῷ.",translation:"나는 신에게 분노하며 죽을 몸의 인간으로서 가시채를 향해 발길질하기보다, 차라리 그에게 제사를 드리겠다."}],connection:"사도행전 26장 14절의 πρὸς κέντρα λακτίζειν(가시채를 향해 발길질하다)은 이 비극의 πρὸς κέντρα λακτίζοιμι와 같은 속담적 표현이다. Johnson은 이 표현이 그리스 문학에 널리 쓰였다고 설명한다. 바울의 변론에서는 예수님의 부름에 저항하던 자신의 행동을 설명하는 말로 나온다.",caution:"비극의 장면은 신에게 맞서는 펜테우스 왕을 경고하는 말이고, 사도행전은 예수님의 소명에 순종하게 된 바울의 회고다. 공통 속담의 실제 용례를 보여 주는 자료이며, 두 작품 전체의 관계는 문학적 모방을 논의하는 별도의 연구 주제다.",commentary:"Luke Timothy Johnson, The Acts of the Apostles, 사도행전 26장 14절 주해.",edition:"Gilbert Murray 편, Euripidis Fabulae, 3권, Oxford: Clarendon Press, 1913. Perseus 고정 전사본.",license:s,sources:[{label:"Perseus 고정판 원문(XML)",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0006/tlg017/tlg0006.tlg017.perseus-grc2.xml"},{label:"고정판 판본 정보",url:"https://github.com/PerseusDL/canonical-greekLit/blob/bcc5df0602f3b3fe6fefe1e1d575602a25ab1db6/data/tlg0006/tlg017/__cts__.xml"},{label:"원문 이용 조건(CC BY-SA 4.0)",url:"https://creativecommons.org/licenses/by-sa/4.0/"}],keywords:["가시채","발길질","속담","소명","바울","에우리피데스","바카이","디오니소스","펜테우스"]}]}}]);